with recent_inventory as (select *, date_format(last_restock, 'MMM yyyy') as last_restock_label from inventory where product_id in (2, 5, 7, 10)), agg as (select product_id, month(last_restock) as last_restock_month, sum(quantity) as total_quantity, round(stddev(quantity), 2) as stddev_quantity from recent_inventory group by product_id, month(last_restock)) select * from agg order by last_restock_month desc, product_id limit 10;
